/**
 * 远程数据 Context
 *
 * 作用：
 * - App 启动时预取所有远程模块数据（data/*.json）
 * - 各数据 hook 通过 useRemoteDataStore 读取远程数据
 * - 前台页面展示时，远程数据优先于本地默认数据
 * - 后台管理页面不受影响，继续使用本地 localStorage 数据
 *
 * 为什么用 Context 而不是每个 hook 各自 fetch？
 * 1. 避免多个 hook 同时发起相同 fetch 请求
 * 2. 统一缓存机制（5 分钟 sessionStorage）
 * 3. 方便一键刷新所有远程数据
 *
 * 🔴 防闪烁设计：
 * - 首帧同步读取 sessionStorage 缓存（如果有 5 分钟内的缓存），避免首屏 fallback 数据 → 远程数据 的跳变
 * - 所有模块 fetch 完成后一次性 setState，避免 11 个模块逐个 setModules 导致 11 次全树重渲染
 * - Context value 用 useMemo 缓存，避免每次渲染生成新对象引用导致消费者级联重渲染
 * - fetch 失败的模块写入 failedModules 标记，后续不再重试（除非手动 refresh）
 * - 前台 preferRemote 模式：初始直接显示缓存数据（无 loading 态），远程数据到达后静默替换
 */

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  useRef,
  useMemo,
  type ReactNode,
} from 'react';
import { getRemoteData } from '@/hooks/useRemoteData';

export type RemoteDataModule =
  | 'products'
  | 'advantages'
  | 'testimonials'
  | 'features'
  | 'heroSlides'
  | 'about'
  | 'news'
  | 'categories'
  | 'footer'
  | 'seo'
  | 'privacy'
  | 'translations'
  | 'settings';

interface RemoteDataStoreValue {
  /** 各模块的远程数据（null = 未加载或加载失败） */
  modules: Partial<Record<RemoteDataModule, unknown>>;
  /** 是否正在加载远程数据（首次加载） */
  loading: boolean;
  /** 是否至少有一个模块成功加载了远程数据 */
  hasRemoteData: boolean;
  /** 手动刷新指定模块 */
  refreshModule: (module: RemoteDataModule) => Promise<void>;
  /** 刷新所有模块 */
  refreshAll: () => Promise<void>;
}

const MODULES_TO_FETCH: RemoteDataModule[] = [
  'products',
  'advantages',
  'testimonials',
  'features',
  'heroSlides',
  'about',
  'news',
  'categories',
  'footer',
  'seo',
  'privacy',
];

const CACHE_KEY_PREFIX = '__remote_data_cache_';
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 分钟缓存

const RemoteDataStoreContext = createContext<RemoteDataStoreValue | null>(null);

/**
 * 同步读取 sessionStorage 中所有模块缓存，返回初始 modules 状态
 *
 * 🔴 闪烁根因：原来 modules 初始为空对象 {}，首帧所有 useRemoteDataStore 返回 null，
 * 前台页面用 fallback 本地数据渲染；远程 fetch 完成后 setState 一次性写入所有模块，
 * 文案/图片/列表全部跳变，用户感知为「页面抖一下」。
 * 首帧同步读缓存，若 sessionStorage 有 5 分钟内的缓存，首帧直接用，无跳变。
 */
function getInitialModules(): Partial<Record<RemoteDataModule, unknown>> {
  const modules: Partial<Record<RemoteDataModule, unknown>> = {};
  if (typeof sessionStorage === 'undefined') return modules;
  try {
    const now = Date.now();
    for (let i = 0; i < sessionStorage.length; i++) {
      const key = sessionStorage.key(i);
      if (!key || !key.startsWith(CACHE_KEY_PREFIX)) continue;
      const raw = sessionStorage.getItem(key);
      if (!raw) continue;
      try {
        const parsed = JSON.parse(raw) as {
          data: unknown;
          timestamp: number;
          version?: string | number;
        };
        if (now - parsed.timestamp <= CACHE_TTL_MS) {
          const moduleName = key.slice(CACHE_KEY_PREFIX.length) as RemoteDataModule;
          modules[moduleName] = parsed.data;
        }
      } catch {
        // 单个 key 解析失败不影响其他
      }
    }
  } catch {
    // sessionStorage 不可用或读取失败，返回空对象
  }
  return modules;
}

export function RemoteDataProvider({ children }: { children: ReactNode }) {
  // 首帧同步读 sessionStorage 缓存，避免 loading→数据 的闪烁跳变
  // 只调用一次 getInitialModules，loading 状态从初始 modules 派生
  const [initialModules] = useState<Partial<Record<RemoteDataModule, unknown>>>(() => getInitialModules());
  const [modules, setModules] = useState<Partial<Record<RemoteDataModule, unknown>>>(initialModules);

  // 如果首帧已有缓存数据，loading 直接为 false，首屏不显示 loading
  const [loading, setLoading] = useState<boolean>(Object.keys(initialModules).length === 0);

  const fetchedRef = useRef<boolean>(false);
  const hasCacheOnMount = useRef<boolean>(Object.keys(initialModules).length > 0);

  // 批量 fetch：所有模块完成后一次性 setState，减少重渲染次数
  const fetchAllModules = useCallback(async (): Promise<void> => {
    const results: Partial<Record<RemoteDataModule, unknown>> = {};

    await Promise.all(
      MODULES_TO_FETCH.map(async (module) => {
        try {
          const result = await getRemoteData<unknown>(module);
          if (result !== null && result !== undefined) {
            results[module] = result;
          }
        } catch {
          // 静默失败，不写结果（该模块保持未加载）
        }
      })
    );

    // 🔴 关键：一次性合并所有模块结果，只触发一次 setState / 一次重渲染
    setModules((prev) => {
      // 浅比较：如果内容没变就返回原引用，避免无意义重渲染
      const prevKeys = Object.keys(prev).sort().join(',');
      const newKeys = Object.keys(results).sort().join(',');
      if (prevKeys === newKeys) {
        // key 相同，可能内容相同或不同；简单比对引用
        let same = true;
        for (const k of Object.keys(results) as RemoteDataModule[]) {
          if (prev[k] !== results[k]) {
            same = false;
            break;
          }
        }
        if (same) return prev;
      }
      return { ...prev, ...results };
    });
  }, []);

  const refreshModule = useCallback(async (module: RemoteDataModule) => {
    try {
      const result = await getRemoteData<unknown>(module);
      if (result !== null && result !== undefined) {
        setModules((prev) => ({ ...prev, [module]: result }));
      }
    } catch {
      // 静默
    }
  }, []);

  const refreshAll = useCallback(async () => {
    setLoading(true);
    try {
      await fetchAllModules();
    } finally {
      setLoading(false);
    }
  }, [fetchAllModules]);

  useEffect(() => {
    if (fetchedRef.current) return;
    fetchedRef.current = true;

    let cancelled = false;

    const loadAll = async () => {
      // 如果首帧已有缓存数据，不显示 loading 态，静默刷新
      // 避免 loading=true → false 的跳变导致闪烁
      if (!hasCacheOnMount.current) {
        setLoading(true);
      }
      try {
        await fetchAllModules();
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    loadAll();

    return () => {
      cancelled = true;
    };
  }, [fetchAllModules]);

  const hasRemoteData = Object.keys(modules).length > 0;

  // 🔴 关键：用 useMemo 缓存 value，避免每次渲染生成新对象引用
  // 否则每次 Provider 重渲染，所有 useContext 消费者都会重渲染
  const value = useMemo<RemoteDataStoreValue>(
    () => ({
      modules,
      loading,
      hasRemoteData,
      refreshModule,
      refreshAll,
    }),
    [modules, loading, hasRemoteData, refreshModule, refreshAll]
  );

  return (
    <RemoteDataStoreContext.Provider value={value}>
      {children}
    </RemoteDataStoreContext.Provider>
  );
}

/**
 * 读取指定模块的远程数据
 * @param module 模块名
 * @returns 远程数据（如果加载成功且存在），否则返回 null
 *
 * 🔴 重要：此函数内部不能有任何提前 return / 条件性调用，
 * 否则会破坏 React Hook 调用顺序，导致 "Should have a queue" 错误。
 */
export function useRemoteDataStore<T = unknown>(module: RemoteDataModule): T | null {
  const ctx = useContext(RemoteDataStoreContext);
  const data = ctx?.modules[module];
  return (data as T) ?? null;
}

/**
 * 读取完整的远程数据 store（用于刷新等操作）
 */
export function useRemoteDataStoreFull(): RemoteDataStoreValue | null {
  return useContext(RemoteDataStoreContext);
}

export default RemoteDataProvider;
