/**
 * 远程数据读取 Hook
 *
 * 功能：
 * 1. 前台页面从 GitHub Pages 同域路径 /data/{module}.json 读取最新数据
 *    - 部署到 GitHub Pages 后，data/ 目录在根路径，直接相对路径 fetch
 *    - 不需要 Token，普通访客匿名访问
 * 2. fetch 失败时回退到本地默认数据，绝不白屏
 * 3. 5 分钟缓存机制（sessionStorage），避免每次切换页面重复 fetch
 * 4. 版本号机制：数据文件含 _version 字段，版本变化时更新缓存
 *
 * 使用方式：
 *   const { data, loading, fromRemote } = useRemoteData('products', defaultData);
 *
 * 数据文件路径格式：
 *   data/products.json
 *   data/advantages.json
 *   data/testimonials.json
 *   data/features.json
 *   data/hero-slides.json
 *   data/about.json
 *   data/news.json
 *   data/categories.json
 *   data/footer.json
 *   data/seo.json
 *   data/privacy.json
 */

import { useState, useEffect, useRef } from 'react';

export const CACHE_KEY_PREFIX = '__remote_data_cache_';
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 分钟缓存
const FAILED_KEY_PREFIX = '__remote_data_failed_';
const FAILED_TTL_MS = 5 * 60 * 1000; // 失败后 5 分钟内不重试

interface RemoteDataCache<T> {
  data: T;
  version?: string | number;
  timestamp: number;
  fromRemote: boolean;
}

/**
 * 从缓存读取数据
 */
function readCache<T>(module: string): RemoteDataCache<T> | null {
  if (typeof sessionStorage === 'undefined') return null;
  try {
    const raw = sessionStorage.getItem(CACHE_KEY_PREFIX + module);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as RemoteDataCache<T>;
    // 检查缓存是否过期
    if (Date.now() - parsed.timestamp > CACHE_TTL_MS) {
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

/**
 * 写入缓存
 */
function writeCache<T>(module: string, data: T, version?: string | number, fromRemote = true) {
  if (typeof sessionStorage === 'undefined') return;
  try {
    const cache: RemoteDataCache<T> = {
      data,
      version,
      timestamp: Date.now(),
      fromRemote,
    };
    sessionStorage.setItem(CACHE_KEY_PREFIX + module, JSON.stringify(cache));
  } catch {
    // sessionStorage 可能被禁用或容量不足，静默失败
  }
}

/**
 * 检查模块是否在失败冷却期内（避免失败后反复重试）
 */
function isModuleFailed(module: string): boolean {
  if (typeof sessionStorage === 'undefined') return false;
  try {
    const raw = sessionStorage.getItem(FAILED_KEY_PREFIX + module);
    if (!raw) return false;
    const timestamp = Number(raw);
    if (Number.isNaN(timestamp)) return false;
    return Date.now() - timestamp < FAILED_TTL_MS;
  } catch {
    return false;
  }
}

/**
 * 标记模块为失败状态
 */
function markModuleFailed(module: string) {
  if (typeof sessionStorage === 'undefined') return;
  try {
    sessionStorage.setItem(FAILED_KEY_PREFIX + module, String(Date.now()));
  } catch {
    // ignore
  }
}

/**
 * 获取远程 JSON 数据
 * 不使用 Token，直接相对路径 fetch（GitHub Pages 同域部署）
 * 有缓存 + 失败冷却机制
 */
async function fetchRemoteJson<T>(module: string): Promise<T | null> {
  try {
    const dataFile = getDataFilePath(module);
    const res = await fetch(dataFile, {
      method: 'GET',
      headers: { 'Accept': 'application/json' },
      cache: 'no-cache',
    });

    if (!res.ok) {
      // 404 等错误直接返回 null，走兜底
      return null;
    }

    const contentType = res.headers.get('content-type') || '';
    if (!contentType.includes('json') && !contentType.includes('text')) {
      return null;
    }

    const data = await res.json();
    return data as T;
  } catch {
    // 网络错误、CORS 错误等，静默返回 null
    return null;
  }
}

/**
 * 根据模块名映射到数据文件路径
 */
function getDataFilePath(module: string): string {
  const pathMap: Record<string, string> = {
    products: 'data/products.json',
    advantages: 'data/advantages.json',
    testimonials: 'data/testimonials.json',
    features: 'data/features.json',
    heroSlides: 'data/hero-slides.json',
    about: 'data/about.json',
    news: 'data/news.json',
    categories: 'data/categories.json',
    footer: 'data/footer.json',
    seo: 'data/seo.json',
    privacy: 'data/privacy.json',
    translations: 'data/translations.json',
    settings: 'data/settings.json',
  };
  return pathMap[module] || `data/${module}.json`;
}

interface UseRemoteDataOptions<T> {
  /** 初始默认数据（本地兜底） */
  fallback: T;
  /** 是否启用远程读取（默认 true） */
  enabled?: boolean;
  /** 自定义版本号对比字段（默认 _version） */
  versionField?: string;
  /** 强制刷新（忽略缓存） */
  forceRefresh?: boolean;
}

interface UseRemoteDataResult<T> {
  /** 最终数据（优先远程，失败则本地兜底） */
  data: T;
  /** 是否正在加载远程数据 */
  loading: boolean;
  /** 数据是否来自远程 GitHub */
  fromRemote: boolean;
  /** 错误信息（如有） */
  error: string | null;
  /** 手动刷新 */
  refresh: () => void;
}

/**
 * 远程数据读取 Hook
 *
 * 行为：
 * 1. 初始渲染时先返回 fallback 数据（避免白屏）
 * 2. 同时检查 sessionStorage 缓存，有有效缓存则立即替换为缓存数据
 * 3. 异步 fetch 远程数据
 * 4. fetch 成功 → 更新 data + 写入缓存
 * 5. fetch 失败 → 保持 fallback 或缓存数据，不报错
 */
export function useRemoteData<T>(module: string, options: UseRemoteDataOptions<T>): UseRemoteDataResult<T> {
  const { fallback, enabled = true, versionField = '_version', forceRefresh = false } = options;

  const [data, setData] = useState<T>(fallback);
  const [loading, setLoading] = useState<boolean>(false);
  const [fromRemote, setFromRemote] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [refreshKey, setRefreshKey] = useState<number>(0);
  const fetchedRef = useRef<boolean>(false);

  useEffect(() => {
    if (!enabled) return;

    // 1. 先读缓存
    if (!forceRefresh) {
      const cached = readCache<T>(module);
      if (cached) {
        setData(cached.data);
        setFromRemote(cached.fromRemote);
      }
    }

    // 2. 已经 fetch 过一次且数据来自远程，短时间内不再重复 fetch
    if (fetchedRef.current && !forceRefresh) {
      return;
    }

    let cancelled = false;
    setLoading(true);

    const doFetch = async () => {
      try {
        const result = await fetchRemoteJson<T>(module);

        if (cancelled) return;

        if (result !== null) {
          // 远程数据获取成功
          setData(result);
          setFromRemote(true);
          setError(null);

          // 写入缓存
          const version = (result as any)?.[versionField];
          writeCache(module, result, version, true);
          fetchedRef.current = true;
        } else {
          // fetch 失败或返回空，保持现有数据（fallback 或缓存）
          setError('Remote data fetch failed, using local fallback');
          // 失败不写缓存，下次还可以重试
        }
      } catch (err) {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : String(err));
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    doFetch();

    return () => {
      cancelled = true;
    };
  }, [module, enabled, versionField, forceRefresh, refreshKey]);

  const refresh = () => {
    setRefreshKey((k) => k + 1);
    fetchedRef.current = false;
  };

  return { data, loading, fromRemote, error, refresh };
}

/**
 * 清空远程数据缓存（所有模块）
 */
export function clearRemoteDataCache(): void {
  if (typeof sessionStorage === 'undefined') return;
  try {
    const keys: string[] = [];
    for (let i = 0; i < sessionStorage.length; i++) {
      const key = sessionStorage.key(i);
      if (key && key.startsWith(CACHE_KEY_PREFIX)) {
        keys.push(key);
      }
    }
    keys.forEach((k) => sessionStorage.removeItem(k));
  } catch {
    // 静默失败
  }
}

/**
 * 手动获取远程数据（非 Hook 版本，可在任何地方调用）
 */
export async function getRemoteData<T>(module: string): Promise<T | null> {
  // 1. 先读缓存
  const cached = readCache<T>(module);
  if (cached) {
    return cached.data;
  }

  // 2. 失败冷却期内直接返回 null，不发起 fetch
  if (isModuleFailed(module)) {
    return null;
  }

  // 3. 真正 fetch
  const data = await fetchRemoteJson<T>(module);
  if (data !== null && data !== undefined) {
    // 成功：写入缓存
    const version = (data as Record<string, unknown>)._version as string | number | undefined;
    writeCache<T>(module, data, version, true);
    return data;
  }

  // 4. 失败：标记失败，下次直接跳过
  markModuleFailed(module);
  return null;
}

export default useRemoteData;
